          saturation: 0,
          lightness: 0,
          threshold: 128,
          posterizeLevels: 4,
          blurRadius: 6,
        },
        'filter-1',
      ),
    ).toMatchObject({ id: 'filter-1', type: 'gaussian-blur', radius: 6 });
  });
});

